using System.IO.Compression;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Xml.Linq;
using Jindan.Engine.Package;
static class Program{
 static int Passed,Failed;static readonly string Folder=Path.Combine(AppContext.BaseDirectory,"goldens");
 static void Check(bool value,string message="Assertion failed"){if(!value)throw new Exception(message);}
 static void Throws(Action action,params string[] codes){try{action();}catch(PackageException e){Check(codes.Contains(e.Code),"Unexpected code: "+e.Code);return;}throw new Exception("Expected package rejection.");}
 static void Test(string name,Action action){try{action();Passed++;Console.WriteLine("PASS "+name);}catch(Exception e){Failed++;Console.WriteLine("FAIL "+name+" "+e.GetType().Name+": "+e.Message);}}
 static byte[] Read(string name)=>File.ReadAllBytes(Path.Combine(Folder,name));
 static string Hash(byte[] b)=>Convert.ToHexStringLower(SHA256.HashData(b));
 static Dictionary<string,byte[]> Entries(byte[] bytes){using var zip=new ZipArchive(new MemoryStream(bytes,false),ZipArchiveMode.Read);return zip.Entries.ToDictionary(e=>e.FullName,e=>{using var s=e.Open();using var b=new MemoryStream();s.CopyTo(b);return b.ToArray();},StringComparer.Ordinal);}
 static byte[] Zip(IEnumerable<KeyValuePair<string,byte[]>> entries){using var output=new MemoryStream();using(var zip=new ZipArchive(output,ZipArchiveMode.Create,true))foreach(var (name,bytes)in entries){using var s=zip.CreateEntry(name).Open();s.Write(bytes);}return output.ToArray();}
 static byte[] MutateRecovery(Action<JsonNode> change){var e=Entries(Read("recovery.zip"));var m=JsonNode.Parse(e["recovery.json"])!;change(m);e["recovery.json"]=Encoding.UTF8.GetBytes(m.ToJsonString());return Zip(e);}
 public static int Main(){using var manifest=JsonDocument.Parse(Read("manifest.json"));var golden=manifest.RootElement;foreach(var item in golden.GetProperty("cases").EnumerateArray()){var name=item.GetProperty("name").GetString()!;Test("shared repaired-JS golden: "+name,()=>{var bytes=Read(name);var before=bytes.ToArray();Check(Hash(bytes)==item.GetProperty("sha256").GetString(),"Frozen golden SHA mismatch; do not rewrite fixture.");if(!item.GetProperty("jsAccepted").GetBoolean()){Throws(()=>NativePackage.InspectHwpx(bytes),name=="dtd.hwpx"?"INVALID_XML":"INVALID_ARCHIVE");}else{var inventory=NativePackage.InspectHwpx(bytes);var expected=item.GetProperty("expected");Check(!inventory.ReportReady&&inventory.ManifestValidated&&inventory.Sha256==expected.GetProperty("sha256").GetString());var entries=expected.GetProperty("entries").EnumerateArray().ToArray();Check(entries.Length==inventory.Entries.Count);for(var i=0;i<entries.Length;i++){var e=entries[i];var actual=inventory.Entries[i];Check(actual.Name==e.GetProperty("name").GetString()&&actual.Size==e.GetProperty("size").GetInt64()&&actual.Sha256==e.GetProperty("sha256").GetString(),"Entry hash/size mismatch.");}var sections=expected.GetProperty("sections").EnumerateArray().ToArray();Check(sections.Length==inventory.Sections.Count);for(var i=0;i<sections.Length;i++){var s=sections[i];var actual=inventory.Sections[i];Check(actual.Name==s.GetProperty("name").GetString()&&actual.Paragraphs==s.GetProperty("paragraphs").GetInt32()&&actual.TextSlots==s.GetProperty("textSlots").GetInt32()&&actual.Cells==s.GetProperty("cells").GetInt32()&&actual.Pictures==s.GetProperty("pictures").GetInt32()&&actual.SlotTextSha256==s.GetProperty("slotTextSha256").GetString(),"Section slot/cell/picture/text mismatch.");}}Check(bytes.SequenceEqual(before),"Caller input mutated.");});}
 Test("bounded entry count, expanded bytes, XML bytes and input bytes",()=>{var bytes=Read("normal.hwpx");foreach(var limits in new[]{new PackageLimits(MaxEntries:1),new PackageLimits(MaxExpandedBytes:1),new PackageLimits(MaxXmlBytes:32),new PackageLimits(MaxInputBytes:10)})Throws(()=>NativePackage.InspectHwpx(bytes,limits),"INVALID_ARCHIVE");Throws(()=>NativePackage.InspectHwpx(bytes,new(MaxEntries:20001)),"INVALID_LIMIT");});
 Test("native stricter manifest checks do not silently drop missing sections or references",()=>{var entries=Entries(Read("normal.hwpx"));entries.Remove("Contents/content.hpf");Throws(()=>NativePackage.InspectHwpx(Zip(entries)),"MISSING_MANIFEST");Check(!NativePackage.InspectHwpx(Zip(entries),validateManifest:false).ManifestValidated);entries=Entries(Read("normal.hwpx"));entries.Remove("Contents/section1.xml");Throws(()=>NativePackage.InspectHwpx(Zip(entries)),"INVALID_MANIFEST");});
 Test("package-relative OPF href paths resolve without rewriting source",()=>{var entries=Entries(Read("normal.hwpx"));var xml=XDocument.Parse(Encoding.UTF8.GetString(entries["Contents/content.hpf"]));foreach(var item in xml.Descendants().Where(e=>e.Name.LocalName=="item")){var href=item.Attribute("href")!;if(href.Value.StartsWith("Contents/"))href.Value=href.Value[9..];else if(href.Value.StartsWith("BinData/"))href.Value="../"+href.Value;}entries["Contents/content.hpf"]=Encoding.UTF8.GetBytes(xml.ToString());Check(NativePackage.InspectHwpx(Zip(entries)).Sections.Count==2);});
 Test("recovery exact shared SHA, file hashes, parent links and fresh analysis requirement",()=>{var g=golden.GetProperty("recovery");var bytes=Read("recovery.zip");var before=bytes.ToArray();var result=NativePackage.VerifyRecovery(bytes,golden.GetProperty("projectId").GetString(),g.GetProperty("sha256").GetString());Check(result.Sha256==g.GetProperty("sha256").GetString()&&!result.ReportReady&&!result.StandaloneMetadataPreserved);var expected=g.GetProperty("files").EnumerateArray().ToArray();Check(result.Files.Count==expected.Length);for(var i=0;i<expected.Length;i++){var e=expected[i];var r=result.Files[i];Check(r.Id==e.GetProperty("id").GetString()&&r.Role==e.GetProperty("role").GetString()&&r.Sha256==e.GetProperty("sha256").GetString()&&r.Size==e.GetProperty("size").GetInt64()&&r.Entry==e.GetProperty("entry").GetString()&&r.RequiresReanalysis==e.GetProperty("requiresReanalysis").GetBoolean()&&r.ParentIds.SequenceEqual(e.GetProperty("parentIds").EnumerateArray().Select(p=>p.GetString()!)));}Check(bytes.SequenceEqual(before));});
 Test("recovery project and exact archive hash mismatch blocked",()=>{var bytes=Read("recovery.zip");Throws(()=>NativePackage.VerifyRecovery(bytes,"project:other"),"BINDING_MISMATCH");Throws(()=>NativePackage.VerifyRecovery(bytes,expectedSha256:new string('0',64)),"BINDING_MISMATCH");});
 Test("recovery payload mutation blocked by actual bytes hash",()=>{var entries=Entries(Read("recovery.zip"));var name=entries.Keys.First(k=>k.StartsWith("files/"));entries[name][0]^=1;Throws(()=>NativePackage.VerifyRecovery(Zip(entries)),"BINDING_MISMATCH");});
 Test("recovery roles, parent existence, derived parents and cycles fail closed",()=>{foreach(var mutate in new Action<JsonNode>[] {m=>m["files"]![1]!["role"]="unknown",m=>m["files"]![1]!["parentIds"]=new JsonArray("missing"),m=>m["files"]![1]!["parentIds"]=new JsonArray(),m=>{m["files"]![0]!["role"]="evidence";m["files"]![0]!["parentIds"]=new JsonArray("saved");}})Throws(()=>NativePackage.VerifyRecovery(MutateRecovery(mutate)),"INVALID_RECOVERY");});
 Test("recovery duplicate/unregistered/path payloads rejected",()=>{var entries=Entries(Read("recovery.zip"));var duplicate=entries.ToList();duplicate.Add(new("recovery.json",entries["recovery.json"]));Throws(()=>NativePackage.VerifyRecovery(Zip(duplicate)),"INVALID_ARCHIVE");entries["files/"+new string('a',64)+".bin"]=[1];Throws(()=>NativePackage.VerifyRecovery(Zip(entries)),"INVALID_RECOVERY");entries=Entries(Read("recovery.zip"));entries["../escape"]=[1];Throws(()=>NativePackage.VerifyRecovery(Zip(entries)),"INVALID_ARCHIVE");});
 Test("unsafe recovery state keys and oversized manifests rejected",()=>{Throws(()=>NativePackage.VerifyRecovery(MutateRecovery(m=>m["state"]!["__proto__"]=new JsonObject())),"INVALID_RECOVERY");var entries=Entries(Read("recovery.zip"));entries["recovery.json"]=new byte[8*1024*1024+1];Throws(()=>NativePackage.VerifyRecovery(Zip(entries)),"INVALID_RECOVERY");});
 Test("recovery excessive JSON depth and nonfinite numbers match the shared state boundary",()=>{var entries=Entries(Read("recovery.zip"));var node=JsonNode.Parse(entries["recovery.json"])!;JsonNode deep=new JsonObject();for(var i=0;i<66;i++)deep=new JsonObject{{"nested",deep}};node["state"]=deep;entries["recovery.json"]=Encoding.UTF8.GetBytes(node.ToJsonString(new System.Text.Json.JsonSerializerOptions{MaxDepth=128}));Throws(()=>NativePackage.VerifyRecovery(Zip(entries)),"INVALID_RECOVERY");entries=Entries(Read("recovery.zip"));var text=Encoding.UTF8.GetString(entries["recovery.json"]);text=text.Replace("\"state\":{", "\"state\":{\"nonfinite\":1e400,",StringComparison.Ordinal);entries["recovery.json"]=Encoding.UTF8.GetBytes(text);Throws(()=>NativePackage.VerifyRecovery(Zip(entries)),"INVALID_RECOVERY");});
 Test("pre-cancellation and malformed empty input preserve fail-closed behavior",()=>{var ct=new CancellationToken(true);try{NativePackage.InspectHwpx(Read("normal.hwpx"),ct:ct);throw new Exception("Expected cancellation.");}catch(OperationCanceledException){}try{NativePackage.VerifyRecovery(Read("recovery.zip"),ct:ct);throw new Exception("Expected cancellation.");}catch(OperationCanceledException){}Throws(()=>NativePackage.InspectHwpx(Array.Empty<byte>()),"INVALID_ARCHIVE");});
 Console.WriteLine($"RESULT nativePackagePass={Passed} fail={Failed} restorationRemains=Hybrid-JS reportReady=false supervisorAccepted=false");return Failed==0?0:1;}
}
